import{_ as t,o as a,c as r,a5 as n}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"Family Learning Agreement: Fourteen Days of Negotiable Support","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/family-learning-agreement.en.md","filePath":"public/downloads/worksheets/family-learning-agreement.en.md","lastUpdated":1795488252000}'),o={name:"public/downloads/worksheets/family-learning-agreement.en.md"};function i(s,e,d,l,h,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="family-learning-agreement-fourteen-days-of-negotiable-support" tabindex="-1">Family Learning Agreement: Fourteen Days of Negotiable Support <a class="header-anchor" href="#family-learning-agreement-fourteen-days-of-negotiable-support" aria-label="Permalink to &quot;Family Learning Agreement: Fourteen Days of Negotiable Support&quot;">​</a></h1><p>This is not a parent-issued contract or a promise a child must sign in obedience. It is a private worksheet that lets a learner and parent or guardian write separately, read each other accurately, and use fourteen days of evidence to choose the next step.</p><p>Keep it in a private family location. Do not include passwords, identity numbers, precise addresses, internal school accounts, medical records, or private information about teachers and classmates. Do not publish the agreement, baseline, or failed samples unless the learner understands the scope, relevant people have authorised the use, and the content has been minimised.</p><h2 id="_1-write-separately-then-read-together" tabindex="-1">1. Write Separately, Then Read Together <a class="header-anchor" href="#_1-write-separately-then-read-together" aria-label="Permalink to &quot;1. Write Separately, Then Read Together&quot;">​</a></h2><h3 id="learner-first" tabindex="-1">Learner First <a class="header-anchor" href="#learner-first" aria-label="Permalink to &quot;Learner First&quot;">​</a></h3><p>One real thing I want to become easier after two weeks:<br> What I can already complete:<br> Where I most often stop:<br> Help that works for me:<br> Help that makes starting harder or makes honesty less safe:<br> Time and capacity I can carry today:</p><h3 id="parent-or-guardian-next" tabindex="-1">Parent or Guardian Next <a class="header-anchor" href="#parent-or-guardian-next" aria-label="Permalink to &quot;Parent or Guardian Next&quot;">​</a></h3><p>Specific facts I have observed:<br> What I am most concerned about:<br> Concerns supported by evidence:<br> Parts that remain my interpretation:<br> Time, space, device, or communication support I can provide:<br> Monitoring, substituted work, or public sharing I will not do:</p><p>When reading together, do not rebut immediately. Restate the other person&#39;s meaning until they consider it substantially accurate.</p><h2 id="_2-write-one-shared-question" tabindex="-1">2. Write One Shared Question <a class="header-anchor" href="#_2-write-one-shared-question" aria-label="Permalink to &quot;2. Write One Shared Question&quot;">​</a></h2><p>The one question these fourteen days answer:<br> School or life situation where it occurs:<br> Explicit school requirement:<br> Learner&#39;s own acceptance standard:<br> Safety and responsibility boundary the adult must protect:<br> Result that supports continuation:<br> Result that supports reduction, pause, or closure:</p><p>The question must permit an unsuccessful result. “Can I retell the main idea of a parallel text after two weeks?” preserves reality more easily than “increase vocabulary by 500 words”.</p><h2 id="_3-preserve-the-baseline" tabindex="-1">3. Preserve the Baseline <a class="header-anchor" href="#_3-preserve-the-baseline" aria-label="Permalink to &quot;3. Preserve the Baseline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Task and constraints</th><th>Learner&#39;s independent result</th><th>Where prompts entered</th><th>Raw evidence location</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>What the baseline can show:<br> What it still cannot show:<br> The one condition this experiment changes:</p><p>An adult may help preserve the file but does not give the complete answer before the baseline is finished.</p><h2 id="_4-three-capacity-modes" tabindex="-1">4. Three Capacity Modes <a class="header-anchor" href="#_4-three-capacity-modes" aria-label="Permalink to &quot;4. Three Capacity Modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>When it applies</th><th>Learner action to preserve</th><th>Adult support to preserve</th></tr></thead><tbody><tr><td>Full</td><td></td><td></td><td></td></tr><tr><td>Compressed</td><td></td><td></td><td></td></tr><tr><td>Recovery</td><td></td><td></td><td></td></tr></tbody></table><p>Latest ending time:<br> Work explicitly not repaid:<br> Minimum return action within 24 hours after interruption:</p><p>A recovery day may contain no learning artifact. Safety, basic care, communication, and preparing the next entry can be the whole result.</p><h2 id="_5-adult-support-list" tabindex="-1">5. Adult Support List <a class="header-anchor" href="#_5-adult-support-list" aria-label="Permalink to &quot;5. Adult Support List&quot;">​</a></h2><p>Choose only two or three for these two weeks:</p><ul><li>[ ] Protect one time box from casual interruption.</li><li>[ ] Prepare school-designated material or necessary equipment.</li><li>[ ] Help contact a teacher or confirm an assignment requirement.</li><li>[ ] Give no more than three concrete feedback points after the learner&#39;s first version.</li><li>[ ] Give one reminder at the agreed time without repeated questioning.</li><li>[ ] Help save versions and the next entry point.</li><li>[ ] Agree to downgrade or pause when capacity falls.</li></ul><p>The adult explicitly will not:</p><ul><li>[ ] Write or answer in the learner&#39;s place, or ask AI to produce work the learner submits under their name.</li><li>[ ] Inspect the screen, chat history, or minute-by-minute status all day.</li><li>[ ] Send artifacts, grades, or failures to unrelated relatives or public platforms.</li><li>[ ] Shame through comparison with classmates, siblings, or past high points.</li><li>[ ] Repay the plan through lost sleep, removed basic rest, or continuing conflict.</li></ul><h2 id="_6-ai-and-data-agreement" tabindex="-1">6. AI and Data Agreement <a class="header-anchor" href="#_6-ai-and-data-agreement" aria-label="Permalink to &quot;6. AI and Data Agreement&quot;">​</a></h2><p>Permitted platform and account:<br> Current platform age/guardian rules checked: yes / no / not applicable<br> Does the school permit AI for this task?<br> AI may: ask / explain / give feedback / create parallel practice / other<br> AI may not:<br> Independent version the learner submits first:<br> Evidence saved after each use:<br> Retelling or independent action after the session closes:</p><p>Never upload:</p><ul><li>[ ] Name, school, class, identity document, precise address, or private contact details.</li><li>[ ] Face, voiceprint, health, family relationships, or non-minimised grade records.</li><li>[ ] Private information or unauthorised work from teachers, classmates, or other third parties.</li><li>[ ] Internal school accounts, test answers, restricted material, or sensitive family information.</li></ul><p>When the platform, school, or family cannot confirm the boundary, use paper, offline material, synthetic data, or a teacher-approved alternative first.</p><h2 id="_7-feedback-rules" tabindex="-1">7. Feedback Rules <a class="header-anchor" href="#_7-feedback-rules" aria-label="Permalink to &quot;7. Feedback Rules&quot;">​</a></h2><p>One main question kept in each review:<br> Maximum number of adult feedback points:<br> How the learner may reject or question feedback:<br> Fact to establish first during disagreement:<br> When a teacher should participate:</p><p>Feedback form:</p><p>I observed:<br> Effect on the task:<br> What I remain uncertain about:<br> One thing I suggest testing next:</p><p>Avoid “you are just…”, “you never…”, and “everyone else can…”.</p><h2 id="_8-fourteen-day-evidence" tabindex="-1">8. Fourteen-Day Evidence <a class="header-anchor" href="#_8-fourteen-day-evidence" aria-label="Permalink to &quot;8. Fourteen-Day Evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time point</th><th>Condition</th><th>Independent result</th><th>Feedback received</th><th>Still unknown</th></tr></thead><tbody><tr><td>Day-one baseline</td><td></td><td></td><td></td><td></td></tr><tr><td>Immediate revision</td><td></td><td></td><td></td><td></td></tr><tr><td>Delayed retest</td><td></td><td></td><td></td><td></td></tr><tr><td>Transfer under one new condition</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>Chat duration, streaks, and reminder counts are process traces. Key judgment returns to artifacts, problems, recordings, classroom use, and performance after prompts are removed.</p><h2 id="_9-pause-and-support-gate" tabindex="-1">9. Pause and Support Gate <a class="header-anchor" href="#_9-pause-and-support-gate" aria-label="Permalink to &quot;9. Pause and Support Gate&quot;">​</a></h2><p>Safety, physical, sleep, emotional, school, or family conditions that pause the experiment immediately:<br> Trusted adult the learner can contact first:<br> School contact route:<br> Qualified local or emergency support route:<br> Work that does not need repayment after a pause:</p><p>For persistent functional difficulty, thoughts of harm, violence, bullying, threats, or unsafe communication, protect safety and seek appropriate support rather than diagnosing or handling the situation through this worksheet.</p><h2 id="_10-two-week-review-learner-speaks-first" tabindex="-1">10. Two-Week Review: Learner Speaks First <a class="header-anchor" href="#_10-two-week-review-learner-speaks-first" aria-label="Permalink to &quot;10. Two-Week Review: Learner Speaks First&quot;">​</a></h2><h3 id="learner" tabindex="-1">Learner <a class="header-anchor" href="#learner" aria-label="Permalink to &quot;Learner&quot;">​</a></h3><p>One thing that genuinely became easier:<br> One thing still impossible or prompt-dependent:<br> Most useful support:<br> Monitoring that added no value or made me uncomfortable:<br> Action I am willing to continue:</p><h3 id="parent-or-guardian" tabindex="-1">Parent or Guardian <a class="header-anchor" href="#parent-or-guardian" aria-label="Permalink to &quot;Parent or Guardian&quot;">​</a></h3><p>Artifacts and facts I observed:<br> Control or failed demand I reduced:<br> Concern that remains unsupported by enough evidence:<br> Support I will keep in the next cycle:</p><h3 id="shared-decision" tabindex="-1">Shared Decision <a class="header-anchor" href="#shared-decision" aria-label="Permalink to &quot;Shared Decision&quot;">​</a></h3><p>Continue / reduce / change one condition / pause or stop:<br> Evidence:<br> Smallest next task:<br> Next review date:<br> Teacher or professional involvement needed:</p><h2 id="closing-support-must-face-review-too" tabindex="-1">Closing: Support Must Face Review Too <a class="header-anchor" href="#closing-support-must-face-review-too" aria-label="Permalink to &quot;Closing: Support Must Face Review Too&quot;">​</a></h2><p>Families often review whether the learner completed the task and rarely review whether adult support worked. This agreement asks both sides for evidence: did the task become clearer, did support reduce friction, and can the relationship still tell the truth?</p><p>When help becomes only surveillance, substituted work, and transferred anxiety, it too must shrink or stop. Useful support may not make a learner do more immediately. It helps them see the problem, state a need, own a version, and know whom to contact when difficulty grows.</p><p>Related chapter: <a href="https://byoungd.github.io/up/en/threads/part-4/family-learning" target="_blank" rel="noreferrer">Family Learning: Return Ownership of Growth to the Learner</a> | <a href="https://byoungd.github.io/up/en/threads/part-4/week-1" target="_blank" rel="noreferrer">First Week Practice</a> | <a href="https://byoungd.github.io/up/en/templates/evidence-chain" target="_blank" rel="noreferrer">Evidence Chain Template</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/family-learning-agreement" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-09-02. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',54)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
